
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ssb_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ssb_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.515661452286674e+00, -4.427141900828271e+00, -4.303506820881504e+00, -4.133150758730154e+00, -3.903132314100736e+00, -3.602031538844007e+00, -3.226479861298806e+00, -2.791526291037166e+00, -2.332336762283595e+00, -1.866061043389715e+00, -1.291906440680923e+00, -7.489694689108519e-01, -6.336479641373650e-01, -5.135249967588313e-01, -3.772109045874830e-01, -2.480530988790387e-01, -1.346932468026587e-01, -4.959469136681306e-02, -1.081270321194983e-02, -1.216203107690358e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


